  function progressList(){let list;const api=dialog('진행상태 변경 설정',view=>{list=view.body;const add=button('신규(F2)',()=>progressEdit());add.disabled=!can();view.footer.append(add,button('닫기',view.close));});const refresh=()=>{list.replaceChildren();const table=N('table',undefined,'self-table'),head=N('tr');['불러올메뉴','생성할메뉴','설정'].forEach(x=>head.append(N('th',x)));table.append(head);for(const rule of config().inventoryFeatures.progressRules){const tr=N('tr');tr.append(N('td',menuName(rule.from)),N('td',menuName(rule.to)));const cell=N('td');cell.append(button('설정',()=>progressEdit(rule,refresh)));tr.append(cell);table.append(tr);}list.append(table);};refresh();function progressEdit(rule,done=refresh){editSection('진행상태 변경 설정','inventoryFeatures',(body,draft)=>{const menus=menuOptions(),from=select('불러올메뉴',[['','선택'],...menus],rule?.from||''),to=select('생성할메뉴',[['','선택'],...menus],rule?.to||''),mode=select('진행상태 변경',[['no','변경안함'],['yes','변경']],rule?.enabled?'yes':'no'),state=select('진행상태 기본값',[['진행','진행중'],['완료','완료']],rule?.progress||'완료');from.disabled=to.disabled=Boolean(rule)||!can();mode.disabled=state.disabled=!can();body.append(field('불러올메뉴',from),field('생성할메뉴',to),field('진행상태 변경',mode),field('진행상태 기본값',state));return ()=>{if(!from.value||!to.value||from.value===to.value)throw Error('서로 다른 메뉴를 선택하세요.');const rules=draft.progressRules.filter(x=>!rule||x.from!==rule.from||x.to!==rule.to);if(rules.some(x=>x.from===from.value&&x.to===to.value))throw Error('같은 메뉴 조합이 이미 있습니다.');return {...draft,progressRules:[...rules,{from:from.value,to:to.value,enabled:mode.value==='yes',progress:state.value}]};};}).d.addEventListener('close',done);}return api;}
  const menuName=id=>root.InventoryCore?.types[id]||id,menuOptions=()=>Object.entries(root.InventoryCore?.types||{});
  function catalog(){if(options.page==='defaults')return defaultsCatalog;return tab==='재고'?inventoryCatalog:(featureCatalog[tab]||{});}
  function tree(){const wrap=N('div',undefined,'self-settings-tree');for(const [section,groups]of Object.entries(catalog())){const outer=N('details');outer.open=true;outer.append(N('summary',section));for(const [group,labels]of Object.entries(groups)){const matches=labels.filter(label=>!query||(section+' '+group+' '+label).toLowerCase().includes(query.toLowerCase()));if(!matches.length)continue;const inner=N('details');inner.open=true;inner.append(N('summary',group));for(const label of matches){let action;if(options.page==='defaults'&&defaultKeys[label]&&(label!=='공급가액'&&label!=='부가세'||section==='입력기본값설정'))action=()=>editDefault(label);if(options.page==='features'&&tab==='재고'){if(['품목범위','집계조건','불러오기조건'].includes(label))action=()=>editImport(label);if(label==='진행상태 변경 설정')action=progressList;}const row=N('div',undefined,'self-settings-row'),b=button(label,action||(()=>{}));b.disabled=!action;if(!action)b.title='상세 동작을 직접 확인하지 않아 아직 지원하지 않습니다.';row.append(b);if(action){let value='';if(options.page==='defaults'){const v=config().commonDefaults[defaultKeys[label]];value=typeof v==='boolean'?(v?'사용':'사용안함'):({round:'반올림',floor:'버림',ceil:'올림'}[v]??(v===' '?'공백':v));}else if(label==='품목범위'){const v=config().inventoryFeatures.import;value=['품목코드',...(v.matchName?['품목명']:[]),...(v.matchSpec?['규격']:[])].join(', ');}else if(label==='집계조건')value=config().inventoryFeatures.import.grouping==='item'?'품목별':'라인별';else if(label==='불러오기조건')value=config().inventoryFeatures.import.view==='remaining'?'미현황화면':'조회화면';else if(label==='진행상태 변경 설정')value=config().inventoryFeatures.progressRules.length+'건';row.append(N('span',String(value??''),'self-settings-value'));}else row.append(N('span','미확인','self-settings-value'));inner.append(row);}outer.append(inner);}if(outer.querySelector('button'))wrap.append(outer);}if(!wrap.children.length)wrap.append(N('p',query?'검색된 항목이 없습니다.':'이 탭의 항목은 아직 대조하지 않았습니다.'));return wrap;}
  function mappingEdit(){editSection('매핑센터 신규','menuMappings',(body,draft)=>{const from=select('불러올메뉴',[['','선택'],...menuOptions()],''),to=select('생성할메뉴',[['','선택'],...menuOptions()],''),toField=field('생성할메뉴',to);toField.hidden=true;from.disabled=to.disabled=!can();from.onchange=()=>{toField.hidden=!from.value;if(!from.value)to.value='';};body.append(field('불러올메뉴',from),toField,button('다시작성',()=>{from.value=to.value='';toField.hidden=true;from.focus();}));return ()=>{if(!from.value||!to.value||from.value===to.value)throw Error('서로 다른 불러올메뉴와 생성할메뉴를 선택하세요.');if(draft.rules.some(x=>x.from===from.value&&x.to===to.value))throw Error('동일한 메뉴 매핑이 이미 있습니다.');return {...draft,rules:[...draft.rules,{id:'MAP-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),from:from.value,to:to.value,enabled:true}]};};});}
  function download(columns,rows){const clean=value=>{let s=String(value??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';},blob=new Blob(['\uFEFF'+[columns,...rows].map(row=>row.map(clean).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=N('a');a.href=url;a.download='menu-mappings.csv';a.click();URL.revokeObjectURL(url);}
