  function drawPage(){host.replaceChildren();host.classList.add('self-settings');host.append(N('h2',options.page==='defaults'?'기본값설정':options.page==='features'?'기능설정':'매핑센터'));if(options.page==='mappings'){mappingPage();return;}const tabs=N('nav',undefined,'self-settings-tabs');for(const name of options.page==='defaults'?['공통']:['공통','회계','재고','관리','그룹웨어','데이터센터']){const b=button(name,()=>{tab=name;drawPage();});b.setAttribute('aria-pressed',String(tab===name));tabs.append(b);}const search=N('input');search.setAttribute('aria-label','설정 검색');search.value=query;const content=N('div'),redraw=()=>content.replaceChildren(tree());search.oninput=()=>{query=search.value;redraw();};const collapse=button('전체접기',()=>{for(const node of content.querySelectorAll('details'))node.open=false;});host.append(tabs,field('검색',search),collapse,content);redraw();}
